#!/usr/bin/env python3
"""Generate ../tables.go: the CPython 3.11 (Unicode 14.0.0) character data behind
str.lower(), str.upper(), str.isspace(), str.isidentifier(), str.isdigit() and the
decimal digits int()/float() accept.

    PYTHONPATH=. ~/cf-test/.venv/bin/python server/internal/pystr/testdata/gen_tables.py

Case-ignorable and cased (the Final_Sigma context of str.lower) are not exposed by
Python, so they are measured through str.lower itself:
  (c + 'Σ').lower() ends in 'ς'      <=> not ignorable(c) and cased(c)
  ('AΣ' + c).lower()[1] == 'ς' and
  ('A' + c + 'Σ').lower() ends in 'ς' <=> ignorable(c)
"""
import sys
import unicodedata
from pathlib import Path

assert sys.version_info[:2] == (3, 11), sys.version


def chars():
    for cp in range(0x110000):
        if 0xD800 <= cp <= 0xDFFF:
            continue
        yield cp, chr(cp)


def ranges(cps):
    out = []
    for cp in cps:
        if out and out[-1][1] == cp - 1:
            out[-1][1] = cp
        else:
            out.append([cp, cp])
    return out


lower, upper, space, ignorable, cased, decimal, digit = [], [], [], [], [], [], []
xid_start, xid_continue = [], []
for cp, c in chars():
    if c.lower() != c and cp != 0x3A3:
        lower.append((cp, c.lower()))
    if c.upper() != c:
        upper.append((cp, c.upper()))
    if c.isidentifier():
        xid_start.append(cp)
    if ('a' + c).isidentifier():
        xid_continue.append(cp)
    if c.isspace():
        space.append(cp)
    if c.isdigit():
        digit.append(cp)
    if ('AΣ' + c).lower()[1] == 'ς' and ('A' + c + 'Σ').lower()[-1] == 'ς':
        ignorable.append(cp)
    elif (c + 'Σ').lower()[-1] == 'ς':
        cased.append(cp)
    d = unicodedata.decimal(c, -1)
    if d >= 0:
        decimal.append((cp, d))

digit_runs = []
for cp, d in decimal:
    if digit_runs and digit_runs[-1][1] == cp - 1 and digit_runs[-1][2] + (cp - digit_runs[-1][0]) == d:
        digit_runs[-1][1] = cp
    else:
        digit_runs.append([cp, cp, d])


def go_string(s):
    return '"' + ''.join(f'\\U{ord(ch):08X}' if ord(ch) > 0xFFFF else (f'\\u{ord(ch):04X}' if ord(ch) > 0x7E or ord(ch) < 0x20 or ch in '"\\' else ch) for ch in s) + '"'


lines = [f'// Code generated by testdata/gen_tables.py (Python {sys.version.split()[0]}, Unicode {unicodedata.unidata_version}); DO NOT EDIT.',
         '', 'package pystr', '']


def emit_ranges(name, doc, cps):
    lines.append(f'// {name} {doc}')
    lines.append(f'var {name} = [][2]rune{{')
    for lo, hi in ranges(cps):
        lines.append(f'\t{{0x{lo:X}, 0x{hi:X}}},')
    lines.append('}')
    lines.append('')


lines.append('// lowerTable maps the code points whose str.lower() differs from themselves (U+03A3 aside,')
lines.append('// handled by the Final_Sigma rule) to their lower-case text, sorted by code point.')
lines.append('var lowerTable = []struct {')
lines.append('\tr rune')
lines.append('\ts string')
lines.append('}{')
for cp, s in lower:
    lines.append(f'\t{{0x{cp:X}, {go_string(s)}}},')
lines.append('}')
lines.append('')
lines.append('// upperTable maps the code points whose str.upper() differs from themselves to their')
lines.append('// upper-case text (full case mapping), sorted by code point.')
lines.append('var upperTable = []struct {')
lines.append('\tr rune')
lines.append('\ts string')
lines.append('}{')
for cp, s in upper:
    lines.append(f'\t{{0x{cp:X}, {go_string(s)}}},')
lines.append('}')
lines.append('')
emit_ranges('identStartRanges', 'are the code points c for which c.isidentifier() is true (XID_Start and "_").', xid_start)
emit_ranges('identContinueRanges', 'are the code points c for which ("a" + c).isidentifier() is true (XID_Continue).', xid_continue)
emit_ranges('spaceRanges', 'are the code points for which str.isspace() is true.', space)
emit_ranges('digitRanges', 'are the code points for which str.isdigit() is true.', digit)
emit_ranges('caseIgnorableRanges', 'are the Case_Ignorable code points of the Final_Sigma rule.', ignorable)
emit_ranges('casedRanges', 'are the cased code points that are not case-ignorable.', cased)
lines.append('// decimalRuns are runs of consecutive decimal digits (Py_UNICODE_TODECIMAL):')
lines.append('// {first, last, value of first}.')
lines.append('var decimalRuns = [][3]rune{')
for lo, hi, d in digit_runs:
    lines.append(f'\t{{0x{lo:X}, 0x{hi:X}, {d}}},')
lines.append('}')
lines.append('')
Path(__file__).resolve().parent.parent.joinpath('tables.go').write_text('\n'.join(lines), encoding='utf-8')
print(len(lower), len(upper), len(xid_start), len(xid_continue), len(space), len(digit), len(ignorable), len(cased), len(digit_runs))
